using Oathx.Core;
using Oathx.Entity;
using Oathx.Widget;

/// <summary>
/// Manages the SV login page lifecycle.
/// </summary>
public class LoginSystem : RuntimeSystem
{
    /// <summary>
    /// Load and open the SV login page through UISystem.
    /// </summary>
    /// <returns>True after starting the page open request; false if the system is inactive.</returns>
    public override bool OnActive()
    {
        if (!IsActive())
            return false;

        UISystem.GetSingleton().OpenWidget<UILogin>((widget) => {
            if (widget)
            {
                widget.vm.EnterClick = (sender) => EnterGame(widget.vm);
                widget.vm.CanEnter = true;

                XApp.GetSingleton().ShowLaunchBackground();
            }
        });

        return true;
    }

    /// <summary>
    /// Publish local login success when the player enters the game.
    /// </summary>
    /// <param name="vm">View model controlling the enter button.</param>
    /// <returns>True when the local login success event has been queued.</returns>
    private bool EnterGame(VMLogin vm)
    {
        if (!IsActive() || !vm || !vm.CanEnter)
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        return XPluginUtility.PostEvent(new LoginSucceed() {
            pid = master.GetAttr(MasterPropertyDef.PID)
        });
    }

    /// <summary>
    /// Release subscriptions and close the SV login page when deactivated.
    /// </summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        UISystem.GetSingleton().CloseWidget<UILogin>(immediate: true);
    }
}

using Oathx.Entity;
using Oathx.HttpProtocol;
using UnityEngine;

/// <summary>
/// 
/// </summary>
[Initialize]
public partial class LoginEntity : XEntity
{
    /// <summary>
    /// constructor
    /// </summary>
    public int pid
    { get; set; }

    /// <summary>
    /// login time
    /// </summary>
    public long loginAt
    { get; set; }

    /// <summary>
    /// create time
    /// </summary>
    public long tmcreate
    { get; set; }

    /// <summary>
    /// query login entity
    /// </summary>
    /// <param name="response"></param>
    /// <returns></returns>
    public bool Refresh(LoginResponse response)
    {
        pid = response.pid; loginAt = response.loginAt; tmcreate = response.tmcreate;
        return true;
    }
}

using Oathx.Widget;

/// <summary>
/// SV login view with serialized Widget Metadata bindings.
/// </summary>
[Config("Assets/Data/Widgets/SVLogin/SVLogin.prefab", WidgetLayer.center, cacheWidget: false)]
public class UILogin : UIWidget<VMLogin>
{
    /// <summary>
    /// Refresh the account display from the existing login entity.
    /// </summary>
    /// <param name="entity">Current login data.</param>
    /// <returns>True when the view model was refreshed.</returns>
    public bool Invalidate(LoginEntity entity)
    {
        if (!entity || !vm)
            return false;

        vm.Username = entity.pid > 0 ? entity.pid.ToString() : string.Empty;
        return true;
    }
}

using Oathx.Widget;

/// <summary>
/// Generated bindings for the SV login page.
/// </summary>
public partial class VMLogin : VM
{
    /// <summary>
    /// Login button callback.
    /// </summary>
    [Binding]
    private ButtonClick enterClick;

    /// <summary>
    /// Whether another login request can be started.
    /// </summary>
    [Binding(typeof(SyncInteractable))]
    private bool canEnter;

    /// <summary>
    /// Selected authentication or game server name.
    /// </summary>
    [Binding(typeof(SyncText))]
    private string serverName;

    /// <summary>
    /// Current login status or retryable failure message.
    /// </summary>
    [Binding(typeof(SyncText))]
    private string serverStatus;

    /// <summary>
    /// Current client resource version.
    /// </summary>
    [Binding(typeof(SyncText))]
    private string versionText;

    /// <summary>
    /// Player identifier obtained from LoginEntity.
    /// </summary>
    [Binding(typeof(SyncText))]
    private string username;

    /// <summary>
    /// Friend suggestions remain hidden until their service is connected.
    /// </summary>
    [Binding(typeof(SyncVisible))]
    private bool friends;
}
